import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import Loading from "../Components/Loading";

const IndividualCourse = () => {
  const [course, setCourse] = useState({});
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState(false);
  const { id } = useParams();

  function fetchAndCourse() {
    setLoading(true);
    axios
      .get(`https://rctmockapi.onrender.com/courses/${id}`)
      .then((res) => {
        setLoading(false);
        setCourse(res.data);
      })
      .catch((err) => {
        setLoading(false);
        setErr(true);
        console.log(err);
      });
  }

  useEffect(() => {
    fetchAndCourse();
  }, [id]);

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <Loading />
      </div>
    );
  }

  return (
    <div className="w-full pb-16">
      {/* Top Banner Card */}
      <div className="max-w-6xl mx-auto px-4 py-8 md:py-12">
        <div className="bg-[#f6d6a0] rounded-2xl shadow-lg border border-[#e5c285] overflow-hidden flex flex-col md:flex-row">
          {/* Image */}
          <div className="md:w-1/2 flex items-center justify-center p-4 md:p-6">
            <img
              src={course.image}
              alt={course.courseName}
              className="w-full h-[280px] md:h-[420px] object-cover rounded-xl shadow-md"
            />
          </div>

          {/* Details */}
          <div className="md:w-1/2 p-6 md:p-10 flex flex-col justify-between">
            <div className="space-y-4">
              <h1 className="text-3xl md:text-5xl font-extrabold text-[#304b62]">
                {course.courseName}
              </h1>
              <h2 className="text-xl font-bold text-[#37464e]">
                For age group of: {course.Age}
              </h2>
              <div>
                <h3 className="text-lg font-bold text-[#304b62] mb-1">
                  About the Course:
                </h3>
                <p className="text-base md:text-lg font-medium text-[#37464e] leading-relaxed">
                  {course.about}
                </p>
              </div>
              <p className="text-2xl font-extrabold text-[#d49539]">
                Price: ₹{course.price}
              </p>
            </div>

            <div className="pt-6">
              <button className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold py-3 px-8 rounded-md transition-colors shadow-md">
                Book a Demo
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* More Information Section */}
      <div className="max-w-6xl mx-auto px-4">
        <h2 className="text-2xl md:text-4xl font-extrabold text-center text-[#304b62] my-8">
          More Information About the Course
        </h2>

        {/* 3 Metric Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12 max-w-4xl mx-auto">
          <div className="bg-[#304b62] rounded-xl p-6 text-center text-white shadow-md">
            <h3 className="text-lg font-bold">
              Course Duration:
              <br />
              <span className="text-xl font-extrabold">{course.courseDuration || "3 Months"}</span>
            </h3>
          </div>
          <div className="bg-[#304b62] rounded-xl p-6 text-center text-white shadow-md">
            <h3 className="text-lg font-bold">
              {course.Schedule || "Regular"}
              <br />
              <span className="text-xl font-extrabold">Daily</span>
            </h3>
          </div>
          <div className="bg-[#304b62] rounded-xl p-6 text-center text-white shadow-md">
            <h3 className="text-lg font-bold">
              Maximum Member Count:
              <br />
              <span className="text-xl font-extrabold">5</span>
            </h3>
          </div>
        </div>

        {/* What will you receive? Card */}
        <div className="max-w-3xl mx-auto bg-[#ebecf3] rounded-2xl p-8 shadow-md">
          <h3 className="text-2xl font-extrabold text-[#304b62] mb-6 pb-2 border-b border-slate-300">
            What will you receive?
          </h3>
          <div className="divide-y divide-slate-300 space-y-6">
            <div className="pt-2">
              <h4 className="text-lg font-bold text-[#304b62] uppercase tracking-wide">
                GAMIFIED PLATFORM
              </h4>
              <p className="text-base text-slate-700 mt-1">
                Earn points and rewards for completing classes and see your ranking on the leaderboard!
              </p>
            </div>
            <div className="pt-6">
              <h4 className="text-lg font-bold text-[#304b62] uppercase tracking-wide">
                PRACTICE SUPPORT
              </h4>
              <p className="text-base text-slate-700 mt-1">
                Get one-click access to Class recordings, Assignments, and supplementary materials!
              </p>
            </div>
            <div className="pt-6">
              <h4 className="text-lg font-bold text-[#304b62] uppercase tracking-wide">
                CERTIFICATION
              </h4>
              <p className="text-base text-slate-700 mt-1">
                Get Certified by TalentGum as you progress towards the next level in Art!
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default IndividualCourse;
